const translations: Record<Language, TranslationSet> = { en, es, it, fr };

export function t(key: TranslationKey, values: Record<string, string | number> = {}): string {
  const template = key in en ? translations[language][key as BaseKey] : extraTranslations[language][key as ExtraKey];
  return template.replace(/\{(\w+)\}/g, (match, name: string) => values[name] === undefined ? match : String(values[name]));
}

export function countText(count: number, one: TranslationKey, many: TranslationKey): string {
  return t(count === 1 ? one : many, { count });
}
